    /// This theme with a custom AI colour, such as `MonarchBrandTheme.aiAccent`.
    /// Replaces the AI roles and the roles that follow them (thinking and
    /// citation). Combine with `withAccent(_:)` for a full brand theme.
    public func withAI(_ ai: MonarchAccent) -> MonarchThemeTokens {
        MonarchThemeTokens(
            id: id,
            isDark: isDark,
            isHighContrast: isHighContrast,
            focusRingWidth: focusRingWidth,
            colors: aiColors(ai.scale(themeID: id)),
            shadows: shadows
        )
    }

